bool FGomokuStage6_CanUseValidateExecuteSeparated::RunTest(const FString& Parameters)
{
	auto* Engine = MakeStage6Engine(2, 15);
	const int32 PlayerId = 1;
	const int32 ItemId = 101;

	if (!TestFalse(TEXT("CanUseItem before add"), UGomokuItemLibrary::CanUseItem(Engine, PlayerId, ItemId)))
		return false;

	bool Added = Engine->AddItemToInventory(PlayerId, ItemId);
	if (!TestTrue(TEXT("AddItemToInventory succeeds"), Added))
		return false;

	if (!TestTrue(TEXT("CanUseItem after add"), UGomokuItemLibrary::CanUseItem(Engine, PlayerId, ItemId)))
		return false;

	FIntPoint TargetCell(0, 0);
	int32 TargetPlayerIndex = -1;

	bool ValidTarget = UGomokuItemLibrary::ValidateTarget(Engine, ItemId, TargetCell, TargetPlayerIndex);
	if (!TestTrue(TEXT("ValidateTarget on empty cell"), ValidTarget))
		return false;

	bool Executed = UGomokuItemLibrary::ExecuteItem(Engine, ItemId, PlayerId, TargetCell, TargetPlayerIndex);
	if (!TestTrue(TEXT("ExecuteItem succeeds"), Executed))
		return false;

	if (!TestFalse(TEXT("CanUseItem after execute is false"), UGomokuItemLibrary::CanUseItem(Engine, PlayerId, ItemId)))
		return false;

	return true;
}

